import{_ as e,o as s,c as t,a4 as o}from"./chunks/framework.BN7V4KR5.js";const g=JSON.parse('{"title":"🐱 Scratch","description":"","frontmatter":{},"headers":[],"relativePath":"Scratch_D.md","filePath":"Scratch_D.md"}'),r={name:"Scratch_D.md"};function n(i,a,d,l,c,p){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="🐱-scratch" tabindex="-1">🐱 Scratch <a class="header-anchor" href="#🐱-scratch" aria-label="Permalink to “🐱 Scratch”">​</a></h1><h2 id="o-que-e" tabindex="-1">O que é? <a class="header-anchor" href="#o-que-e" aria-label="Permalink to “O que é?”">​</a></h2><p><strong>Scratch</strong> é uma linguagem de programação visual e uma plataforma online de criação desenvolvida pelo <strong>MIT Media Lab</strong>, lançada em 2007 e atualmente na versão <strong>3.0</strong> (desde 2019). É a maior plataforma de programação criativa do mundo, com mais de <strong>100 milhões de usuários registrados</strong> em mais de 200 países.</p><p>Em vez de escrever código com texto, o Scratch usa <strong>blocos coloridos que se encaixam como peças de LEGO</strong>. O usuário arrasta, combina e executa esses blocos para criar jogos, animações, histórias interativas e muito mais — tudo diretamente no navegador, sem instalar nada.</p><p>O objetivo do Scratch não é apenas ensinar sintaxe de programação. É ensinar a <strong>pensar computacionalmente</strong> através da criação de projetos que o próprio usuário escolhe e imagina.</p><h2 id="o-que-o-scratch-ensina" tabindex="-1">O que o Scratch ensina? <a class="header-anchor" href="#o-que-o-scratch-ensina" aria-label="Permalink to “O que o Scratch ensina?”">​</a></h2><p>Os conceitos são introduzidos naturalmente conforme o usuário quer fazer coisas mais complexas. Ninguém precisa estudar uma lista de tópicos — a criatividade guia o aprendizado.</p><table tabindex="0"><thead><tr><th>Conceito</th><th>Como aparece no Scratch</th></tr></thead><tbody><tr><td><strong>Sequência</strong></td><td>Blocos executados de cima para baixo</td></tr><tr><td><strong>Eventos</strong></td><td>&quot;Quando a bandeira for clicada&quot;, &quot;quando tecla for pressionada&quot;</td></tr><tr><td><strong>Loops</strong></td><td>Blocos <code>repita</code>, <code>sempre</code>, <code>repita até que</code></td></tr><tr><td><strong>Condicionais</strong></td><td>Blocos <code>se / então / senão</code></td></tr><tr><td><strong>Variáveis</strong></td><td>Armazenar pontuação, vidas, nome do jogador</td></tr><tr><td><strong>Listas</strong></td><td>Sequências de perguntas, itens de inventário</td></tr><tr><td><strong>Funções</strong></td><td>&quot;Meus Blocos&quot; — criar blocos personalizados reutilizáveis</td></tr><tr><td><strong>Paralelismo</strong></td><td>Múltiplos scripts rodando ao mesmo tempo</td></tr><tr><td><strong>Eventos customizados</strong></td><td>Sistema de mensagens entre sprites</td></tr><tr><td><strong>Clonagem</strong></td><td>Criar cópias independentes de um objeto em tempo real</td></tr><tr><td><strong>Coordenadas</strong></td><td>Posicionar sprites no palco com eixos X e Y</td></tr><tr><td><strong>Lógica booleana</strong></td><td>Operadores <code>e</code>, <code>ou</code>, <code>não</code></td></tr></tbody></table><hr><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to “Funcionalidades”">​</a></h2><h3 id="sprites-e-o-palco" tabindex="-1">Sprites e o Palco <a class="header-anchor" href="#sprites-e-o-palco" aria-label="Permalink to “Sprites e o Palco”">​</a></h3><p>O <strong>Palco</strong> é a tela do projeto — onde tudo acontece, com dimensões fixas de 480×360 pixels e um sistema de coordenadas com centro em (0, 0).</p><p><strong>Sprites</strong> são os personagens e objetos do projeto. Cada sprite tem:</p><ul><li><strong>Fantasias</strong> — suas aparências visuais (podendo ter várias para animação)</li><li><strong>Scripts</strong> — os programas que controlam seu comportamento</li><li><strong>Sons</strong> — áudios associados a ele</li></ul><h3 id="categorias-de-blocos" tabindex="-1">Categorias de Blocos <a class="header-anchor" href="#categorias-de-blocos" aria-label="Permalink to “Categorias de Blocos”">​</a></h3><p>Cada categoria tem uma cor própria para identificação rápida:</p><table tabindex="0"><thead><tr><th>Categoria</th><th>Cor</th><th>O que faz</th></tr></thead><tbody><tr><td><strong>Movimento</strong></td><td>🔵 Azul</td><td>Mover, girar, posicionar o sprite no palco</td></tr><tr><td><strong>Aparência</strong></td><td>🟣 Roxo</td><td>Trocar fantasia, mostrar balões de fala, aplicar efeitos visuais</td></tr><tr><td><strong>Som</strong></td><td>🩷 Rosa</td><td>Tocar sons, controlar volume e efeitos de áudio</td></tr><tr><td><strong>Eventos</strong></td><td>🟡 Amarelo</td><td>Gatilhos que iniciam scripts (clique, tecla, mensagem)</td></tr><tr><td><strong>Controle</strong></td><td>🟠 Laranja</td><td>Loops, condicionais, clones, pausas</td></tr><tr><td><strong>Sensores</strong></td><td>🔵 Azul claro</td><td>Detectar colisão, posição do mouse, teclado, webcam</td></tr><tr><td><strong>Operadores</strong></td><td>🟢 Verde</td><td>Matemática, comparações, lógica, texto</td></tr><tr><td><strong>Variáveis</strong></td><td>🟠 Laranja escuro</td><td>Criar e manipular variáveis e listas</td></tr><tr><td><strong>Meus Blocos</strong></td><td>🔴 Vermelho</td><td>Criar blocos personalizados (funções)</td></tr></tbody></table><h3 id="exemplo-de-codigo-—-movimento-com-teclado" tabindex="-1">Exemplo de código — movimento com teclado <a class="header-anchor" href="#exemplo-de-codigo-—-movimento-com-teclado" aria-label="Permalink to “Exemplo de código — movimento com teclado”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>quando 🏴 for clicado</span></span>
<span class="line"><span>sempre</span></span>
<span class="line"><span>    se &lt;tecla [seta direita] pressionada?&gt; então</span></span>
<span class="line"><span>        adicione (5) a x</span></span>
<span class="line"><span>    se &lt;tecla [seta esquerda] pressionada?&gt; então</span></span>
<span class="line"><span>        adicione (-5) a x</span></span>
<span class="line"><span>    se &lt;tecla [seta cima] pressionada?&gt; então</span></span>
<span class="line"><span>        adicione (5) a y</span></span></code></pre></div><h3 id="exemplo-de-codigo-—-coleta-de-pontos-com-variavel" tabindex="-1">Exemplo de código — coleta de pontos com variável <a class="header-anchor" href="#exemplo-de-codigo-—-coleta-de-pontos-com-variavel" aria-label="Permalink to “Exemplo de código — coleta de pontos com variável”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>quando eu começar como clone</span></span>
<span class="line"><span>sempre</span></span>
<span class="line"><span>    se &lt;tocando em [jogador]?&gt; então</span></span>
<span class="line"><span>        adicione (10) a [pontos]</span></span>
<span class="line"><span>        apague este clone</span></span></code></pre></div><h3 id="sistema-de-mensagens" tabindex="-1">Sistema de Mensagens <a class="header-anchor" href="#sistema-de-mensagens" aria-label="Permalink to “Sistema de Mensagens”">​</a></h3><p>Sprites se comunicam por mensagens — um envia, qualquer outro pode receber e reagir:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sprite A:                        Sprite B:</span></span>
<span class="line"><span>quando clicado                   quando eu receber [explosão]</span></span>
<span class="line"><span>    envie [explosão]                 toque o som [Boom]</span></span>
<span class="line"><span>                                     esconda</span></span></code></pre></div><h3 id="clones" tabindex="-1">Clones <a class="header-anchor" href="#clones" aria-label="Permalink to “Clones”">​</a></h3><p>Clones são cópias independentes de um sprite criadas durante a execução. Cada clone roda seu próprio script, mas herda o comportamento original. Fundamentais para jogos com múltiplos inimigos, projéteis ou partículas:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>quando 🏴 for clicado</span></span>
<span class="line"><span>repita (20)</span></span>
<span class="line"><span>    crie um clone de [eu mesmo]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>quando eu começar como clone</span></span>
<span class="line"><span>    vá para x: (aleatório entre -240 e 240) y: (aleatório entre -180 e 180)</span></span>
<span class="line"><span>    sempre</span></span>
<span class="line"><span>        mova (3) passos</span></span>
<span class="line"><span>        se tocar na borda, volte</span></span></code></pre></div><h3 id="meus-blocos-funcoes" tabindex="-1">Meus Blocos (Funções) <a class="header-anchor" href="#meus-blocos-funcoes" aria-label="Permalink to “Meus Blocos (Funções)”">​</a></h3><p>É possível criar blocos personalizados com parâmetros — o equivalente a funções em linguagens tradicionais:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>defina [teleportar para x: (px) y: (py)]</span></span>
<span class="line"><span>    vá para x: (px) y: (py)</span></span>
<span class="line"><span>    toque o som [Pop]</span></span>
<span class="line"><span>    diga [Cheguei!] por (1) segundos</span></span>
<span class="line"><span></span></span>
<span class="line"><span>teleportar para x: (100) y: (50)   ← chamada do bloco</span></span></code></pre></div><h3 id="editor-de-sprites-e-fantasias" tabindex="-1">Editor de Sprites e Fantasias <a class="header-anchor" href="#editor-de-sprites-e-fantasias" aria-label="Permalink to “Editor de Sprites e Fantasias”">​</a></h3><p>O Scratch inclui um editor gráfico completo com dois modos:</p><ul><li><strong>Bitmap</strong> — para pintura pixel a pixel</li><li><strong>Vetorial</strong> — para formas geométricas escaláveis sem perda de qualidade</li></ul><p>Também é possível importar imagens, usar a câmera do computador ou escolher da biblioteca de sprites do próprio Scratch.</p><h3 id="sons-e-musica" tabindex="-1">Sons e Música <a class="header-anchor" href="#sons-e-musica" aria-label="Permalink to “Sons e Música”">​</a></h3><p>Além de uma biblioteca de sons prontos, o Scratch tem um editor de áudio básico para gravar, cortar e aplicar efeitos (eco, reverso, robot). Com a extensão de <strong>Música</strong>, é possível tocar notas e instrumentos por código:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>toque a nota (60 Dó) por (0.5) batidas</span></span>
<span class="line"><span>toque o tambor (1 Bumbo) por (0.25) batidas</span></span>
<span class="line"><span>defina o instrumento como (1 Piano)</span></span></code></pre></div><h3 id="extensoes" tabindex="-1">Extensões <a class="header-anchor" href="#extensoes" aria-label="Permalink to “Extensões”">​</a></h3><p>O Scratch suporta extensões que ampliam suas capacidades:</p><table tabindex="0"><thead><tr><th>Extensão</th><th>O que permite</th></tr></thead><tbody><tr><td><strong>Música</strong></td><td>Tocar instrumentos e notas musicais</td></tr><tr><td><strong>Caneta</strong></td><td>Desenhar no palco enquanto o sprite se move</td></tr><tr><td><strong>Sintetizador de Texto</strong></td><td>Converter texto em fala (TTS)</td></tr><tr><td><strong>Tradução</strong></td><td>Traduzir textos entre idiomas</td></tr><tr><td><strong>Vídeo</strong></td><td>Detectar movimento pela webcam</td></tr><tr><td><strong>micro:bit</strong></td><td>Programar o microcontrolador BBC micro:bit</td></tr><tr><td><strong>LEGO MINDSTORMS</strong></td><td>Controlar robôs LEGO por código</td></tr><tr><td><strong>Makey Makey</strong></td><td>Conectar objetos físicos ao teclado</td></tr></tbody></table><hr><h2 id="a-comunidade" tabindex="-1">A Comunidade <a class="header-anchor" href="#a-comunidade" aria-label="Permalink to “A Comunidade”">​</a></h2><p>Projetos publicados podem ser <strong>curtidos, comentados e remixados</strong> por qualquer usuário. Remixar significa copiar um projeto e modificá-lo livremente — o Scratch mantém automaticamente o histórico de quem remixou o quê.</p><p>Isso transforma o aprendizado em algo social: o usuário não cria apenas para si, mas para uma audiência real.</p><hr><h2 id="para-quem-e" tabindex="-1">Para quem é? <a class="header-anchor" href="#para-quem-e" aria-label="Permalink to “Para quem é?”">​</a></h2><ul><li><strong>Crianças e jovens</strong> de 8 a 16 anos que estão tendo o primeiro contato com programação</li><li><strong>Educadores</strong> que querem ensinar lógica computacional de forma visual e criativa</li><li><strong>Iniciantes de qualquer idade</strong> que querem criar jogos ou animações sem barreiras técnicas</li><li><strong>Quem quer aprender os fundamentos</strong> antes de migrar para Python, JavaScript ou outra linguagem textual</li></ul><hr><h2 id="informacoes-gerais" tabindex="-1">Informações gerais <a class="header-anchor" href="#informacoes-gerais" aria-label="Permalink to “Informações gerais”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Desenvolvedor</strong></td><td>MIT Media Lab (Grupo Lifelong Kindergarten)</td></tr><tr><td><strong>Lançamento</strong></td><td>2007 (v3.0 em janeiro de 2019)</td></tr><tr><td><strong>Plataforma</strong></td><td>Navegador web, aplicativo desktop, tablet</td></tr><tr><td><strong>Linguagem</strong></td><td>Visual (blocos), exportável para HTML5</td></tr><tr><td><strong>Idiomas</strong></td><td>70+</td></tr><tr><td><strong>Usuários registrados</strong></td><td>100 milhões+</td></tr><tr><td><strong>Custo</strong></td><td>Gratuito</td></tr></tbody></table>`,50)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
